Here is the root cause:
The bug arises from unconditionally enabling interrupts in the `rtrs_srv_change_state` function when IO is completed, which can lead to a panic if this function is called in a softirq context. This occurs because the original implementation does not save and restore the interrupt state, potentially allowing interrupts to be enabled when they should be disabled, leading to race conditions or other unexpected behavior.

Here is the patch:

 static bool rtrs_srv_change_state(struct rtrs_srv_path *srv_path,
 				  enum rtrs_srv_state new_state)
 {
 	enum rtrs_srv_state old_state;
 	bool changed = false;
+	unsigned long flags;

-	spin_lock_irq(&srv_path->state_lock);
+	spin_lock_irqsave(&srv_path->state_lock, flags);
 	old_state = srv_path->state;
 	switch (new_state) {
 	case RTRS_SRV_CONNECTED:
 		if (old_state == RTRS_SRV_CONNECTING)
 			changed = true;
 		break;
 	case RTRS_SRV_CLOSING:
 		if (old_state == RTRS_SRV_CONNECTING ||
 		    old_state == RTRS_SRV_CONNECTED)
 			changed = true;
 		break;
 	case RTRS_SRV_CLOSED:
 		if (old_state == RTRS_SRV_CLOSING)
 			changed = true;
 		break;
 	default:
 		break;
 	}
 	if (changed)
 		srv_path->state = new_state;
-	spin_unlock_irq(&srv_path->state_lock);
+	spin_unlock_irqrestore(&srv_path->state_lock, flags);

 	return changed;
 }



